#!/usr/bin/env python3
"""Reuse R6 support evidence without reading raw episodes or reserved test."""
import argparse,json
from pathlib import Path
from export import ROOT,R5,sha,atomic_json

def run(output):
 r=ROOT/'round6_future_validation/support';names=['support_decision.json','htt_support_manifest.json','source_support_manifest.json','INDEPENDENT_AUDIT.json'];evidence={}
 for name in names:
  p=r/name;d=json.loads(p.read_text());evidence[name]={'path':str(p),'sha256':sha(p),'status':d.get('status')}
 h=json.loads((r/'htt_support_manifest.json').read_text());d=json.loads((r/'support_decision.json').read_text());assert sha(h['contract']['path'])==h['contract']['sha256'];assert sha(h['split_manifest']['path'])==h['split_manifest']['sha256'];assert d['training_triggered'] and d['selected_support']['domain']=='source'
 rows=[{'dataset':'HTT slip','available':True,'sequence':True,'stable_labels':'static','onset':'force-rule-influenced first gross proxy; not independent physical ground truth','support':'R6 all16 fold x H8/10/15/20 fail at least one role trial threshold','independent_new_evaluation':False,'reason':'already used development protocol; do not relabel reserved test or re-split to claim independence','next':'Only future audit under predefined support thresholds, no new training this round'}, {'dataset':'Sparsh source','available':True,'sequence':True,'stable_labels':'current_slip=0 on complete current-label timeline','onset':'first dataset current_slip transition; not extra instrument truth','support':'R6 H1 fit473/506, selection155/165, calibration169/177, outer171/180 positive-event/negative-window trial counts','independent_new_evaluation':False,'reason':'outer is repeatedly used original validation; internal selection/calibration came from legacy train','next':'Existing model robustness only; cannot manufacture independence'}, {'dataset':'NormalFlow','available':Path('/vla1/zjy/tactile_dataset/NormalFlow-dataset/extracted_round1/normalflow_dataset').is_dir(),'sequence':True,'stable_labels':None,'onset':None,'support':'Existing pose/motion supervision is not slip onset truth','independent_new_evaluation':False,'reason':'No audited slip ground truth; test object content remains unread','next':'Not a strict future-slip validation subset'}, {'dataset':'ToucHD-Force/Mani','available':'not inspected','sequence':'unknown','stable_labels':'unknown','onset':'unknown','support':'excluded by scope; downloads not touched','independent_new_evaluation':'unknown','reason':'not a dependency','next':'Only after verified complete availability in separately authorized phase'}]
 output.mkdir(parents=True,exist_ok=True);atomic_json(output/'SUPPORT_AUDIT.json',{'status':'pass','scope':'existing audited datasets only; no exhaustive disk search','evidence':evidence,'rows':rows,'new_future_training':False,'test_content_read':False,'raw_episode_content_read':False,'downloads_touched':False,'independent_slip_physical_truth_established':False,'source_code_sha256':sha(__file__)})
 (output/'SUPPORT_SUMMARY_ZH.md').write_text('# 第九轮独立future数据支持审计\n\n复用第六轮签名记录，核对HTT合同及schema-2划分哈希未变；未读原始试次或test内容。\n\n|数据|现有支持|本轮结论|\n|---|---|---|\n|HTT|连续static/incipient/gross；first-gross受力规则影响；第六轮16组合均至少一个角色数量不足|可做当前检测；不新增future训练，不声称独立物理起点|\n|Sparsh原域|第六轮严格稳定端点有事件支持|已反复使用开发数据，只做已有模型稳健性；不是新增盲测|\n|NormalFlow|连续图像、位姿/运动|没有已核验slip起点，不能将运动当滑移|\n|ToucHD|依用户范围不检查下载或内容|无依赖，无追加训练|\n\n下一阶段若获得新增数据，先固定完整历史、观察窗和当前稳定语义，保留有力变化但不滑的负例，并按物体/试次/泄漏组隔离；沿用至少20/20训练及各选择/校准/评价5/5独立正负试次门槛作为探索启动条件。数量门槛不等于独立性或统计充分。已有开发数据重新划分不能生成独立证据。\n\nHTT force和slip是独立任务试次，不能按同名文件配对真实力；力规则标签限制亦适用于本轮检测论文解释。\n')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);run(p.parse_args().output)
